      `<path d="M0-4h2.8M0-2.9h2.8M0-1.8h1.8" stroke="${color}" stroke-width=".45"/>` +
      `<path d="M4.7-3.4l1.3-3.2" stroke="${C.run}" stroke-width=".8" stroke-linecap="round"/>`,
