      project: Project | null
      skills: Skills
      ui: Ui
      activity: Activity[]
      files: FileHit[]
      waits: Wait[]
      limits: LimitTrack[]
      checks: Check[]
      git: GitState | null
      log: ProjectLog | null
      archive: Archive | null
      tick: number
      /** The project's other live sessions, as last read. */
      others: LiveSession[]
